  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const initialState = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        submitted: false,
        status: "",
      };

      let state = structuredClone(initialState);

      function Field({ id, label, type = "text", required = false, helperText = "" }) {
        const error = getFieldError(id, state.values[id]);
        const shouldShowError = state.submitted || state.touched[id];
        const describedBy = [
          helperText ? `${id}-helper` : "",
          shouldShowError && error ? `${id}-error` : "",
        ]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              value="${escapeHtml(state.values[id])}"
              ${required ? "required" : ""}
              autocomplete="${getAutocomplete(id)}"
              aria-required="${required ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${shouldShowError && error ? 'aria-invalid="true"' : ""}
            />
            ${
              helperText
                ? `<p class="field-helper" id="${id}-helper">${helperText}</p>`
                : ""
            }
            <p class="field-error" id="${id}-error">${shouldShowError && error ? error : ""}</p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <form id="support-form" novalidate>
            <div class="form-grid">
              ${Field({ id: "fullName", label: "Full name", required: true })}
              ${Field({ id: "email", label: "Email address", type: "email", required: true })}
              ${Field({
                id: "phone",
                label: "Phone number",
                type: "tel",
                helperText: "Optional. Enter digits only or use a format like (555) 123-4567.",
              })}
            </div>
            <div class="actions">
              <button type="submit">Send message</button>
              <p class="form-status" id="form-status" aria-live="polite">${state.status}</p>
            </div>
          </form>
        `;
      }

      function SupportPage() {
        return `
          <main id="main-content">
            <section class="page-shell" aria-labelledby="support-heading">
              <p class="eyebrow">Support</p>
              <h1 id="support-heading">Contact our support team</h1>
              <p class="intro">
                Send us your details and we&apos;ll follow up as soon as possible with help for your account,
                billing, or product questions.
              </p>
              ${ContactForm()}
            </section>
          </main>
        `;
      }

      function App() {
        return SupportPage();
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        attachEvents();
      }

      function attachEvents() {
        const form = document.getElementById("support-form");
        const fields = ["fullName", "email", "phone"];

        fields.forEach((fieldId) => {
          const input = document.getElementById(fieldId);

          input.addEventListener("input", (event) => {
            state.values[fieldId] = event.target.value;
            state.status = "";
            if (state.submitted || state.touched[fieldId]) {
              render();
              restoreFocus(fieldId);
            }
          });

          input.addEventListener("blur", () => {
            state.touched[fieldId] = true;
            state.status = "";
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.touched.fullName = true;
          state.touched.email = true;
          state.touched.phone = true;

          const errors = getErrors();
          if (errors.length > 0) {
            state.status = "";
            render();
            const firstInvalid = document.getElementById(errors[0].field);
            if (firstInvalid) {
              firstInvalid.focus();
            }
            return;
          }

          state.status = "Your message is ready to send.";
          render();
        });
      }

      function restoreFocus(fieldId) {
        const input = document.getElementById(fieldId);
        if (input) {
          const end = input.value.length;
          input.focus();
          input.setSelectionRange(end, end);
        }
      }

      function getErrors() {
        return ["fullName", "email", "phone"]
          .map((field) => ({ field, message: getFieldError(field, state.values[field]) }))
          .filter((item) => item.message);
      }

      function getFieldError(field, value) {
        const trimmedValue = value.trim();

        if (field === "fullName" && !trimmedValue) {
          return "Enter your full name.";
        }

        if (field === "email") {
          if (!trimmedValue) {
            return "Enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
        }

        if (field === "phone" && trimmedValue) {
          const phonePattern = /^[+]?[0-9\s().-]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Use digits only or a standard phone format.";
          }
        }

        return "";
      }

      function getAutocomplete(field) {
        if (field === "fullName") return "name";
        if (field === "email") return "email";
        if (field === "phone") return "tel";
        return "off";
      }

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      render();
    </script>
  </body>
</html>
